"""Build a fully offline HTML presentation from frozen result data."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

HTML='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>地铁卡介质客流预测</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6f7;color:#173443;font:16px/1.7 'Microsoft YaHei',sans-serif}main{max-width:1160px;margin:auto;padding:40px 26px}h1{font-size:36px;margin:0}h2{font-size:23px;margin:0 0 15px}p{margin:8px 0}header{border-bottom:2px solid #c8d9df;padding-bottom:25px}.muted{color:#5e7480}.notice{background:#fff2dc;padding:14px 20px;border-left:4px solid #c87927;margin:22px 0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:24px 0}.metric{border-top:3px solid #247f70;padding:15px;background:#fff}.metric strong{font-size:28px;display:block}section{background:white;padding:25px;margin:20px 0;border:1px solid #e0e9ec}button,select,input{font:inherit;padding:7px 12px;border:1px solid #b5c9d1;border-radius:4px;background:#fff;color:#173443}button{cursor:pointer}button:hover{background:#e7eff2}canvas{width:100%;height:360px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;border-bottom:1px solid #dfe7e9;padding:9px}th{background:#edf3f5}figure{margin:20px 0}figure img{max-width:100%;height:auto}a{color:#12668b}details{margin:15px 0}summary{cursor:pointer;font-weight:bold}.line{display:flex;align-items:center;gap:14px;flex-wrap:wrap}#rowDetail{padding:15px;background:#edf4f6;margin-top:12px}.legend{font-size:14px}.blue{color:#145e83}.orange{color:#cb6a2f}@media(max-width:720px){.metrics{grid-template-columns:1fr 1fr}main{padding:22px 12px}h1{font-size:28px}section{padding:14px}canvas{height:300px}table{font-size:12px}}
</style><main><header><p class="muted">北方工业大学 · 综合交通大数据技术实践 7311901</p><h1>地铁卡介质客流预测</h1><p>公开数据质量审计 · 提前一日需求预测 · 高需求分类 · 日型聚类</p></header>
<div class="notice"><b>历史实验快照</b>：数据截止2026-08-16。目标为智能卡与NCMC合计人次，不是全网全部票种客流。回放和末端预测均不是当前实时监测。</div>
<div class="metrics"><div class="metric">测试MAPE<strong id="mape"></strong></div><div class="metric">测试MAE 人次/日<strong id="mae"></strong></div><div class="metric">高需求分类F1<strong id="f1"></strong></div><div class="metric">测试观测日<strong>75</strong></div></div>
<section><h2>预测与实际对照</h2><div class="line"><label for="day">观测日期</label><select id="day"></select><button id="play">播放历史回放</button><button id="reset">显示全部</button><label><input id="interval" type="checkbox" checked>显示名义90%区间</label></div><canvas id="chart" aria-label="75个测试日预测与实际客流折线图"></canvas><p class="legend"><span class="blue">蓝色：实际</span>　<span class="orange">橙色：预测</span>　浅蓝：预测区间；横轴是有记录日顺序，缺失日不作为零值。</p><div id="rowDetail"></div></section>
<section><h2>数据末端预测</h2><p id="forecast"></p><p class="muted">输入信息截止2026-08-16，假设2026-08-17发布，预测2026-08-18。高需求是统计标签，不是拥堵警报。分类分数未经额外校准，区间不保证未来覆盖。</p><a href="results/next_forecast.csv" download>下载末端预测CSV</a></section>
<section><h2>失败案例与使用边界</h2><p>最大误差出现在2026-05-01。总体R²为0.8944，但工作日切片R²为-0.0812；模型仍缺少假日、事件与运营变化信息。</p><div style="overflow:auto"><table><thead><tr><th>日期</th><th>实际</th><th>预测</th><th>绝对误差</th><th>相对误差</th></tr></thead><tbody id="cases"></tbody></table></div><p>名义90%区间在测试期覆盖74/75日（98.67%），平均宽度293,896人次，覆盖较高同时伴随较宽区间。</p></section>
<section><h2>数据与日型</h2><p>460条记录覆盖660个自然日，缺200天。智能卡父子项核验全部通过，QR汇总不一致218行，原值保留，QR不进入主模型。</p><figure><img src="results/figures/04_data_quality.png" alt="月度采集完整性与QR汇总差额"></figure><figure><img src="results/figures/08_clusters.png" alt="卡介质规模和票种比例形成的三类日型"></figure><p>聚类为描述性日型，K=3，开发期轮廓系数0.6054，没有站点空间或乘客身份含义。</p></section>
<section><h2>算法与复现</h2><p>开发期三折验证选择季节性均值，分类选择逻辑回归。预测日d的观测型输入只使用d-2及更早数据。按时间划分开发303日、校准59日、隔离1日、测试75日。</p><details><summary>查看模型比较</summary><img style="max-width:100%" src="results/figures/05_model_comparison.png" alt="三折时间验证候选MAE比较"></details><p><a href="results/predictions.csv" download>全部逐条预测</a>　<a href="results/bad_cases.csv" download>失败案例CSV</a>　<a href="results/clusters.csv" download>聚类结果</a>　<a href="workflow.md">运行工作流</a></p><p>命令：<code>python src/predict.py --date 2026-08-18</code></p><p>过期测试：<code>python src/predict.py --date 2026-09-10</code>，程序应拒绝使用过期快照。</p></section>
<footer class="muted">数据：Mahesh Shantaram / BMRCL，Kaggle版本45，CC0。源代码、数据和报告随项目保存。姓名学号见报告与Agent.md。</footer></main>
<script>const D=__DATA__;const rows=D.predictions;const fmt=x=>Math.round(x).toLocaleString('zh-CN');const $=s=>document.querySelector(s);let playing=null;let count=rows.length;
$('#mape').textContent=D.metrics.test.regression.MAPE_percent.toFixed(2)+'%';$('#mae').textContent=fmt(D.metrics.test.regression.MAE);$('#f1').textContent=D.metrics.test.classification.F1.toFixed(3);
rows.forEach((r,i)=>{let o=document.createElement('option');o.value=i;o.textContent=r.date.slice(0,10);$('#day').appendChild(o)});$('#day').value=rows.length-1;
const f=D.forecast;$('#forecast').textContent=`${f.date}：${fmt(f.prediction)} 人次，名义90%区间 ${fmt(f.lower90)} 至 ${fmt(f.upper90)} 人次。高需求分类分数 ${f.high_probability.toFixed(3)}，判为${f.predicted_high?'高需求':'常规'}。`;
const worst=[...rows].sort((a,b)=>b.absolute_error-a.absolute_error).slice(0,5);for(const r of worst){let tr=document.createElement('tr');for(const v of [r.date.slice(0,10),fmt(r.actual),fmt(r.predicted),fmt(r.absolute_error),r.percentage_error.toFixed(2)+'%']){let td=document.createElement('td');td.textContent=v;tr.appendChild(td)}$('#cases').appendChild(tr)}
function detail(){const r=rows[+$('#day').value];$('#rowDetail').textContent=`${r.date.slice(0,10)}　实际 ${fmt(r.actual)}，预测 ${fmt(r.predicted)}，绝对误差 ${fmt(r.absolute_error)} 人次。真实${r.actual_high?'高需求':'常规'}，预测${r.predicted_high?'高需求':'常规'}。最新可用观测距预测日 ${r.data_age_days} 天。`;}
function draw(){let c=$('#chart'),w=c.clientWidth,h=c.clientHeight,ratio=window.devicePixelRatio||1;c.width=w*ratio;c.height=h*ratio;const g=c.getContext('2d');g.scale(ratio,ratio);g.clearRect(0,0,w,h);let top=20,bottom=h-45,left=65,right=w-15,max=Math.max(...rows.map(r=>r.upper90))*1.05;const xx=i=>left+i/(rows.length-1)*(right-left),yy=v=>bottom-v/max*(bottom-top);g.font='12px Microsoft YaHei';g.strokeStyle='#dfe8eb';g.fillStyle='#516977';for(let i=0;i<=5;i++){let v=max*i/5,y=yy(v);g.beginPath();g.moveTo(left,y);g.lineTo(right,y);g.stroke();g.fillText((v/1e4).toFixed(0)+'万',8,y+4)}
if($('#interval').checked&&count>1){g.fillStyle='rgba(20,94,131,.12)';g.beginPath();for(let i=0;i<count;i++){let r=rows[i];if(i===0)g.moveTo(xx(i),yy(r.upper90));else g.lineTo(xx(i),yy(r.upper90))}for(let i=count-1;i>=0;i--)g.lineTo(xx(i),yy(rows[i].lower90));g.closePath();g.fill()}
for(const [key,color] of [['actual','#145e83'],['predicted','#cb6a2f']]){g.strokeStyle=color;g.lineWidth=1.6;g.beginPath();for(let i=0;i<count;i++){if(i===0)g.moveTo(xx(i),yy(rows[i][key]));else g.lineTo(xx(i),yy(rows[i][key]))}g.stroke()}
g.fillStyle='#516977';for(const i of [0,Math.floor(rows.length/3),Math.floor(rows.length*2/3),rows.length-1])g.fillText(rows[i].date.slice(5,10),xx(i)-15,h-18);let chosen=+$('#day').value;if(chosen<count){g.strokeStyle='#83969d';g.setLineDash([3,3]);g.beginPath();g.moveTo(xx(chosen),top);g.lineTo(xx(chosen),bottom);g.stroke();g.setLineDash([])}}
function stop(){clearInterval(playing);playing=null;$('#play').textContent='播放历史回放'}$('#day').onchange=()=>{detail();draw()};$('#interval').onchange=draw;$('#reset').onclick=()=>{stop();count=rows.length;$('#day').value=rows.length-1;detail();draw()};$('#play').onclick=()=>{if(playing){stop();return}count=1;$('#play').textContent='暂停';playing=setInterval(()=>{$('#day').value=count-1;detail();draw();if(count>=rows.length)stop();else count++},130)};window.addEventListener('resize',draw);detail();draw();</script></html>'''

if __name__=='__main__':
    data=json.loads((ROOT/'results/dashboard_data.json').read_text(encoding='utf-8'))
    (ROOT/'成果演示.html').write_text(HTML.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
    print('Offline dashboard generated')

